      <div><dt>Coordinates</dt><dd className="mono">{Math.abs(lat).toFixed(4)}°{lat >= 0 ? 'N' : 'S'}, {Math.abs(lng).toFixed(4)}°{lng >= 0 ? 'E' : 'W'}</dd></div>
      <div><dt>Updated</dt><dd>{formatRelative(p.updated)}</dd><small>{exactUtcTime(p.updated)}</small></div>
